Remove the manual replace and let `JSON.stringify` handle escaping. Also ensure the environment variable is a string.
```tsx
export function Layout({ children }: { children: React.ReactNode }) {
  const { rootCssClass, resolvedScheme } = useColorScheme();
  const baseUrl = process.env.OMNIBRIDGE_PUBLIC_BASE_URL ?? "https://omnibridge-dev.vercel.app/api/v1";
  return (
    <html lang="en" suppressHydrationWarning className={rootCssClass} style={{ colorScheme: resolvedScheme }}>
      <head>
        {/* ... */}
        <script
          dangerouslySetInnerHTML={{
            __html: `window.__OMNIBRIDGE_BASE_URL__ = ${JSON.stringify(baseUrl)};`,
          }}
        />
        <Links />
      </head>
      {/* ... */}
    </html>
  );
}
